public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
{
    var discount = LoyaltyDiscountPolicy.Discount(query.SubtotalCents, query.LoyaltyTier, query.PromoCode);
    return new(query.SubtotalCents, discount, query.SubtotalCents - discount, query.LoyaltyTier);
}

public CheckoutQuote Handle(QuoteCheckoutQuery query)
{
    var discount = new CalculateLoyaltyDiscount().Handle(
        new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode));
    var shipping = new CalculateShippingFee().Handle(
        new CalculateShippingFeeQuery(discount.TotalCents, query.LoyaltyTier, query.Express));
    return new(discount.TotalCents, shipping, discount.TotalCents + shipping);
}

