+namespace CheckoutPricing.Domain;
+
+public static class LoyaltyDiscountPolicy
+{
+    private const int MinimumSubtotalCents = 3_000;
+    private const int CapCents = 2_000;
+    private const int WelcomeCents = 500;
+    private const int SummerRatePercent = 10;
+    private const int SummerCapCents = 1_500;
+
+    public static int LoyaltyPart(int subtotalCents, LoyaltyTier tier) =>
+        subtotalCents < MinimumSubtotalCents
+            ? 0
+            : Math.Min(CapCents, subtotalCents * RatePercent(tier) / 100);
+
+    public static int Discount(int subtotalCents, LoyaltyTier tier, string? promoCode)
+    {
+        var loyalty = LoyaltyPart(subtotalCents, tier);
+        var total = loyalty + PromoPart(subtotalCents - loyalty, promoCode);
+        return Math.Min(total, subtotalCents);
+    }
+
+    private static int PromoPart(int remainingCents, string? promoCode) =>
+        promoCode?.ToUpperInvariant() switch
+        {
+            "WELCOME5" => WelcomeCents,
+            "SUMMER10" => Math.Min(SummerCapCents, remainingCents * SummerRatePercent / 100),
+            _ => 0
+        };
+
+    private static int RatePercent(LoyaltyTier tier) =>
+        tier switch
+        {
+            LoyaltyTier.Bronze => 5,
+            LoyaltyTier.Silver => 10,
+            LoyaltyTier.Gold => 15,
+            LoyaltyTier.Platinum => 20,
+            _ => 0
+        };
+}

